    let state = copy(defaults);
    function validate(next) {
      return { focus: booleanValue(next.focus), activity: booleanValue(next.activity), hints: booleanValue(next.hints) };
    }
    function render() {
      root.dataset.focus = String(state.focus);
      toggle('focus', state.focus);
      toggle('activity', !state.focus && state.activity, state.focus);
      toggle('hints', !state.focus && state.hints, state.focus);
      text('[data-override]', state.focus ? 'Focus is active. Saved choices are kept.' : 'Using your personal settings');
      text('[data-status]', state.focus ? 'Activity feed and inline hints off' : 'Activity feed ' + (state.activity ? 'on' : 'off') + ' / Inline hints ' + (state.hints ? 'on' : 'off'));
    }
