.sl-component { --choice-surface: var(--nav-surface); --choice-raised: var(--nav-raised); --choice-text: var(--nav-text); --choice-border: var(--nav-border); --choice-accent: var(--nav-accent); --choice-on-accent: var(--nav-accent-ink); --choice-focus: var(--nav-focus); }

