@container (max-width:250px){.sl-component .ov-head{padding-inline:12px}.sl-component .ov-body{padding-inline:12px}.sl-component .ov-foot{padding-inline:12px}.sl-component h2{font-size:17px}.sl-component .ov-foot{gap:5px}.sl-component .ov-foot button{padding-inline:7px}.sl-component .ov-spec th,.sl-component .ov-spec td{padding-inline:2px;font-size:10px}}
