.sl-component { --choice-surface: var(--ov-surface); --choice-raised: var(--ov-field); --choice-text: var(--ov-text); --choice-border: var(--ov-border); --choice-accent: var(--ov-accent); --choice-on-accent: var(--ov-on-accent); --choice-focus: var(--ov-focus); }

