.sl-component .sl-choice-value { min-width: 0; overflow-wrap: anywhere; }
.sl-component .sl-choice-list { display: block; position: absolute; z-index: 8; top: calc(100% + 5px); left: 0; right: 0; padding: 5px; max-height: 164px; overflow-y: auto; overscroll-behavior: contain; scrollbar-width: thin; scrollbar-color: var(--choice-border) transparent; border: 1px solid var(--choice-border); border-radius: 9px; background: var(--choice-surface); box-shadow: 0 6px 16px #0003; visibility: hidden; opacity: 0; transform: translateY(-3px); pointer-events: none; transition: opacity 160ms ease, transform 180ms ease, visibility 0s 180ms; }
