.sl-component .sl-choice:not([data-expanded="true"]) .sl-choice-list { max-height: 0 !important; padding-block: 0; border-block-width: 0; }
.sl-component .sl-choice[data-up="true"] .sl-choice-list { top: auto; bottom: calc(100% + 5px); }
.sl-component .sl-choice[data-expanded="true"] .sl-choice-list { visibility: visible; opacity: 1; transform: none; pointer-events: auto; transition-delay: 0s; }
.sl-component .sl-choice-option { display: flex; align-items: center; justify-content: space-between; gap: 6px; width: 100%; min-height: 34px; margin: 0; padding: 8px; border: 1px solid transparent; border-radius: 6px; font: inherit; font-size: 12px; line-height: 1.4; text-align: left; color: var(--choice-text); background: transparent; cursor: pointer; }
.sl-component .sl-choice-option:hover { background: var(--choice-raised); }
.sl-component .sl-choice-option[aria-selected="true"] { color: var(--choice-on-accent); background: var(--choice-accent); }
.sl-component .sl-choice-option[aria-selected="true"]::after { content: '✓'; flex: none; }
.sl-component .sl-choice :is(button):focus-visible { outline: 2px solid var(--choice-focus); outline-offset: -2px; }
.sl-component .sl-choice-trigger:disabled { opacity: .5; cursor: not-allowed; }
@media (prefers-reduced-motion: reduce) { .sl-component .sl-choice-list { transition: none; transform: none; } }

