.sl-component fieldset{min-width:0;border:0;padding:0;margin:0}
.sl-component legend{color:var(--ov-muted);font-size:11px;padding:0;margin-bottom:7px}
.sl-component .ov-check{display:flex;align-items:center;gap:9px;font-size:12px;padding:7px 0}
.sl-component .ov-check span{min-width:0;overflow-wrap:anywhere}
.sl-component .ov-row{display:flex;align-items:center;justify-content:space-between;gap:8px;min-width:0}
.sl-component .ov-line{padding:10px 0;border-bottom:1px solid color-mix(in srgb,var(--ov-border),transparent 35%)}
.sl-component .ov-options{display:flex;gap:5px;flex-wrap:wrap}
.sl-component .ov-options button{flex:1;padding:7px 5px;font-size:11px}
.sl-component button[aria-pressed=true]{border-color:var(--ov-accent);background:color-mix(in srgb,var(--ov-surface),var(--ov-accent) 14%)}
.sl-component .ov-status{font-size:11px;color:var(--ov-muted);margin-top:10px;min-height:16px;overflow-wrap:anywhere}
.sl-component .ov-mini{font-size:11px;padding:6px 8px;min-height:30px}
.sl-component .ov-list{list-style:none;padding:0;margin:0}
.sl-component .ov-note{background:var(--ov-field);padding:10px;border-radius:9px;border:1px solid var(--ov-border);overflow-wrap:anywhere}
.sl-component .ov-tabs{display:flex;gap:6px;margin-bottom:12px}
.sl-component .ov-tabs button{flex:1;font-size:11px;padding:7px 4px}
.sl-component .ov-calendar{display:grid;grid-template-columns:repeat(7,minmax(0,1fr));gap:2px;margin-top:8px}
.sl-component .ov-calendar button{padding:0;min-height:26px;border:1px solid transparent;border-radius:6px;font-size:11px}
.sl-component .ov-calendar button[data-outside=true]{color:var(--ov-muted);opacity:.65}
.sl-component .ov-calendar button[aria-pressed=true]{background:var(--ov-accent);color:var(--ov-on-accent);opacity:1}
.sl-component .ov-week{display:grid;grid-template-columns:repeat(7,1fr);text-align:center;color:var(--ov-muted);font-size:10px;margin-top:10px}
.sl-component .ov-month{font-size:12px;font-weight:500}
.sl-component .ov-month-nav button{width:30px;min-height:30px;padding:5px}
.sl-component .ov-month-nav svg{width:18px;height:18px}
.sl-component .ov-spec{width:100%;border-collapse:collapse;font-size:11px}
.sl-component .ov-spec th,.sl-component .ov-spec td{text-align:left;padding:10px 4px;border-bottom:1px solid var(--ov-border);overflow-wrap:anywhere}
.sl-component .ov-spec th{font-weight:500;color:var(--ov-muted)}
.sl-component .ov-spec th:first-child{width:40%}
.sl-component .ov-sample{display:grid;place-items:center;min-height:60px;border:1px dashed var(--ov-border);border-radius:10px;margin:4px 0 10px;padding:10px}
.sl-component .ov-sample-chip{display:block;max-width:100%;overflow-wrap:anywhere;padding:8px 12px;background:var(--ov-accent);color:var(--ov-on-accent);border-radius:var(--sample-radius,12px);font-size:14px;opacity:var(--sample-opacity,1);transition:border-radius 180ms ease,opacity 180ms ease}
.sl-component .ov-code{font:11px/1.6 ui-monospace,monospace;white-space:pre-wrap;overflow-wrap:anywhere;margin:8px 0 0;color:var(--ov-muted)}
.sl-component kbd{border:1px solid var(--ov-border);border-bottom-width:2px;border-radius:5px;background:var(--ov-field);padding:2px 5px;font:11px 'Instrument Sans',sans-serif;white-space:nowrap}
.sl-component .ov-swatch{height:58px;background:var(--mixed-color,#a8c0ae);border:1px solid var(--ov-border);border-radius:10px;margin:4px 0 12px}
.sl-component .ov-timer{font-size:46px;font-variant-numeric:tabular-nums;line-height:1.3;letter-spacing:-.04em;text-align:center;margin:10px 0;color:var(--ov-accent)}
.sl-component .ov-progress{width:100%;height:5px;border-radius:4px;appearance:none;display:block;border:0;background:var(--ov-field)}
.sl-component .ov-progress::-webkit-progress-bar{background:var(--ov-field);border-radius:4px}
