    on(root, 'keydown', event => { if (event.key === 'Escape' && pending) { event.preventDefault(); cancel(); } });
    for (const button of all('[data-cancel]')) on(button, 'click', cancel);
    for (const control of all('[data-demo-only]')) control.hidden = true;
    q('[data-caption]').textContent = 'Sample workspace feedback.';

    const name = q('[data-name]'), email = q('[data-email]');
    let checked = false, errors = [];
    render = () => {
      q('[data-check-label]').textContent = state === 'ready' ? 'Details checked' : 'Check details';
      q('[data-check-icon]').hidden = state !== 'ready';
    };
    function check(moveFocus, confirmed) {
      if (destroyed) return false;
      checked = true; errors = [];
      if (!name.value.trim()) errors.push({ field: name, label: 'Enter a workspace name.' });
      // This contact-form example expects an Internet-style dotted domain.
      // Format validation does not verify that an address or mailbox exists.
      if (!email.validity.valid || !/^[^\s@]+@[^\s@.]+(?:\.[^\s@.]+)+$/.test(email.value.trim())) {
