        button.dataset.field = item.field === name ? 'name' : 'email'; li.append(button); q('[data-errors]').append(li);
      }
      state = errors.length ? 'error' : confirmed ? 'ready' : 'idle';
      say(errors.length
        ? errors.length + (errors.length === 1 ? ' field needs attention.' : ' fields need attention.')
        : confirmed ? 'Both fields passed. Nothing was sent.' : 'Details changed. Check them again.');
      sync(); if (moveFocus && errors.length) focus(q('[data-errors] button')); return !errors.length;
    }
    const validate = (moveFocus = true) => check(moveFocus, true);
    on(q('[data-errors]'), 'click', event => { const button = event.target.closest('[data-field]'); if (button) focus(button.dataset.field === 'name' ? name : email); });
    on(q('form'), 'submit', event => { event.preventDefault(); validate(); });
    for (const field of [name,email]) on(field,'input',()=> { if (checked) check(false, false); });
