.sl-component { --choice-surface: var(--fb-surface); --choice-raised: var(--fb-raised); --choice-text: var(--fb-text); --choice-border: var(--fb-border); --choice-accent: var(--fb-accent); --choice-on-accent: var(--fb-on-accent); --choice-focus: var(--fb-focus); }

